/* Verified original Bluff King topic cards. Loaded by the trusted host only.
 * This static game relies on the table rule against searching or inspecting source.
 * Rebuild: node scripts/bluff-compile-topics.cjs */
(function(root){const cards=[{"id":"bk-culture-001","canonicalKnowledgeId":"bk-culture-001","locale":"en","term":"Puzzle jug","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Historical tableware"],"secretAnswer":"A puzzle jug is a drinking vessel with holes and hidden passages that make it hard to drink without spilling.","supportingFacts":["Its neck has holes, so simply tipping it does not work.","It was used for drinking games in taverns."],"revealExplanation":"The V&A's recreated jug has a hidden route under the handle. Covering all but one spout lets the drinker use suction.","sources":[{"title":"V&A — How was it made? A puzzle jug","url":"https://www.vam.ac.uk/articles/how-was-it-made-a-puzzle-jug/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","tableware","drinking-games"]},{"id":"bk-culture-002","canonicalKnowledgeId":"bk-culture-002","locale":"en","term":"Fuddling cup","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Historical tableware","A theatre costume","A wedding custom"],"secretAnswer":"A fuddling cup joins several drinking cups inside, so emptying one can draw liquid from all of them.","supportingFacts":["The cups look separate but their inner spaces are connected.","Such cups were used as joke drinking pots in English taverns."],"revealExplanation":"A drinker who expects one small cup can end up drinking the contents of the whole group.","sources":[{"title":"Seattle Art Museum — Object of the Week: Triplicate vase","url":"https://samblog.seattleartmuseum.org/2018/11/triplicate-vase/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","tableware","drinking-games"]},{"id":"bk-culture-003","canonicalKnowledgeId":"bk-culture-003","locale":"en","term":"Vinaigrette box","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A vinaigrette box is a small container for a sponge soaked in scented vinegar.","supportingFacts":["A lid with small holes holds the sponge while letting its smell out.","People could wear it at the waist or neck, or carry it in a pocket."],"revealExplanation":"Silver examples had gold-covered interiors to protect the silver from the vinegar.","sources":[{"title":"The Met — William Thompson II, Vinaigrette","url":"https://www.metmuseum.org/art/collection/search/207454"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","accessories","scent"]},{"id":"bk-culture-004","canonicalKnowledgeId":"bk-culture-004","locale":"en","term":"Netsuke","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Clothing accessory"],"secretAnswer":"A netsuke is a small toggle that helps hold a hanging container on a Japanese kimono's waist sash.","supportingFacts":["A cord links the toggle to the container.","Wood and ivory were common materials, and many examples are tiny carved figures."],"revealExplanation":"These useful objects also let their owners show wealth through fine materials and skilled carving.","sources":[{"title":"The Met — Netsuke: From Fashion Fobs to Coveted Collectibles","url":"https://www.metmuseum.org/essays/netsuke-from-fashion-fobs-to-coveted-collectibles"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","japan","clothing"]},{"id":"bk-culture-005","canonicalKnowledgeId":"bk-culture-005","locale":"en","term":"Aquamanile","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Historical vessel","A writing method","A street celebration"],"secretAnswer":"An aquamanile is a vessel used to pour water over someone's hands for washing.","supportingFacts":["Medieval examples could be shaped like animals or a mounted knight.","They were used by priests and by people at the dining table."],"revealExplanation":"On the Met's knight-shaped example, the helmet opens for filling, and water comes out near the horse's head.","sources":[{"title":"The Met — Aquamanile in the Form of a Mounted Knight","url":"https://www.metmuseum.org/art/collection/search/468633"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","medieval","washing"]},{"id":"bk-culture-006","canonicalKnowledgeId":"bk-culture-006","locale":"en","term":"Chatelaine","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A chatelaine is a waist hook with chains that carry small useful objects.","supportingFacts":["Its chains could hold keys, scissors, a watch or a small purse.","It attaches to a belt, sash or waistband."],"revealExplanation":"It could also show the authority of the person who kept the keys of a large household.","sources":[{"title":"ASU FIDM Museum — Chatelaine purse","url":"https://fidmmuseum.org/learn/articles/chatelaine-purse"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","accessories","household"]},{"id":"bk-culture-007","canonicalKnowledgeId":"bk-culture-007","locale":"en","term":"Miser's purse","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Historical accessory"],"secretAnswer":"A miser's purse is a long coin purse with a small middle opening that sliding rings close.","supportingFacts":["Coins can be kept in either end of the purse.","Many examples were knitted or crocheted, often with beads."],"revealExplanation":"Some had differently shaped ends so the owner could find the right coins by touch in poor light.","sources":[{"title":"National Museum, Bloemfontein — The Miser's purse","url":"https://nationalmuseumpublications.co.za/the-misers-purse/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","accessories","money"]},{"id":"bk-culture-008","canonicalKnowledgeId":"bk-culture-008","locale":"en","term":"Porte-bouquet","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Fashion accessory","A sailing tool","A musical form"],"secretAnswer":"A porte-bouquet is a small decorative holder for a bunch of fresh flowers.","supportingFacts":["It is also called a posy holder.","Holders were made from materials such as silver, gold and mother-of-pearl."],"revealExplanation":"They could be gifts for important occasions; Queen Victoria received a rich example during a visit to France.","sources":[{"title":"The Fan Museum — Come to the Ball: Posy Holders and Pretty Fans","url":"https://www.thefanmuseum.org.uk/exhibitions/come-to-the-ball"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","flowers","fashion"]},{"id":"bk-culture-009","canonicalKnowledgeId":"bk-culture-009","locale":"en","term":"Burghley Nef","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"The Burghley Nef is a rich salt container made in the shape of a ship.","supportingFacts":["Its hull is a nautilus shell with silver mounts partly covered in gold.","It was made in Paris in the sixteenth century."],"revealExplanation":"Ship-shaped table objects like this could mark the place of a host or honoured guest and show their status.","sources":[{"title":"V&A on Google Arts & Culture — The Burghley Nef","url":"https://artsandculture.google.com/asset/the-burghley-nef/sQGK5XT8Bs5O0Q?hl=en"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","tableware","design"]},{"id":"bk-culture-010","canonicalKnowledgeId":"bk-culture-010","locale":"en","term":"Epergne","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Table decoration"],"secretAnswer":"An epergne is a table centrepiece used to display fruit, sweets or flowers.","supportingFacts":["The Met has an example made from bronze covered in gold.","That example belonged to a set with matching candle holders."],"revealExplanation":"The Met's example was owned by Elizabeth Schuyler, Alexander Hamilton's widow.","sources":[{"title":"The Met — Richmond Room, Epergne","url":"https://www.metmuseum.org/about-the-met/collection-areas/the-american-wing/period-rooms/richmond-room"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","tableware","design"]},{"id":"bk-culture-011","canonicalKnowledgeId":"bk-culture-011","locale":"en","term":"Noken","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Traditional craft","A singing contest","A food dish"],"secretAnswer":"A noken is a knotted or woven bag made by communities in Papua, Indonesia.","supportingFacts":["It is made by hand from wood fibre or leaves.","People use it to carry things such as food, firewood and even babies."],"revealExplanation":"A noken can also be worn at traditional celebrations or given as a peace offering.","sources":[{"title":"UNESCO — Noken multifunctional knotted or woven bag","url":"https://ich.unesco.org/en/USL/noken-multifunctional-knotted-or-woven-bag-handicraft-of-the-peoples-of-papua-00619"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","indonesia","craft"]},{"id":"bk-culture-012","canonicalKnowledgeId":"bk-culture-012","locale":"en","term":"Silbo Gomero","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"Silbo Gomero is a way of communicating Spanish words through whistles on the island of La Gomera.","supportingFacts":["Different whistle sounds stand for vowels and consonants.","Pitch and breaks in the whistles help listeners tell the sounds apart."],"revealExplanation":"It is passed from skilled users to learners and has also been taught in schools.","sources":[{"title":"UNESCO — Whistled language of La Gomera, the Silbo Gomero","url":"https://ich.unesco.org/en/RL/whistled-language-of-the-island-of-la-gomera-canary-islands-the-silbo-gomero-00172"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","language","spain"]},{"id":"bk-culture-013","canonicalKnowledgeId":"bk-culture-013","locale":"en","term":"Yimakan","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Storytelling tradition"],"secretAnswer":"Yimakan is Hezhen storytelling that mixes spoken stories and singing without musical instruments.","supportingFacts":["Performers use different melodies for different characters and parts of a story.","Stories include heroes, battles and the defeat of monsters."],"revealExplanation":"The practice also carries community history and customs, and learners often train with an experienced storyteller.","sources":[{"title":"UNESCO — Decision 20.COM 7.c.2, Hezhen Yimakan storytelling","url":"https://ich.unesco.org/en/Decisions/20.COM/7.c.2"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","china","storytelling"]},{"id":"bk-culture-014","canonicalKnowledgeId":"bk-culture-014","locale":"en","term":"Momoeria","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Seasonal celebration","A writing tool","A cheese-making method"],"secretAnswer":"Momoeria is a New Year celebration with dance, acting and music in villages in northern Greece.","supportingFacts":["Performers move through village streets and visit homes.","The celebration runs from Christmas Day into early January."],"revealExplanation":"Its dancers wear helmets, pleated skirts and traditional shoes, and carry sticks.","sources":[{"title":"UNESCO — Decision 11.COM 10.b.16, Momoeria","url":"https://ich.unesco.org/en/Decisions/11.COM/10.b.16"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","greece","celebration"]},{"id":"bk-culture-015","canonicalKnowledgeId":"bk-culture-015","locale":"en","term":"Al-Qatt Al-Asiri","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"Al-Qatt Al-Asiri is a tradition of painting geometric patterns on interior walls in Asir, Saudi Arabia.","supportingFacts":["Guest rooms are a special focus for this decoration.","The patterns are usually made on a white gypsum base."],"revealExplanation":"Women have traditionally taught the skill by inviting female relatives to help decorate their homes.","sources":[{"title":"UNESCO — Al-Qatt Al-Asiri, interior wall decoration in Asir","url":"https://ich.unesco.org/en/RL/al-qatt-al-asiri-female-traditional-interior-wall-decoration-in-asir-saudi-arabia-01261?RL=01261"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","saudi-arabia","design"]},{"id":"bk-culture-016","canonicalKnowledgeId":"bk-culture-016","locale":"en","term":"Aitysh / Aitys","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Poetry tradition"],"secretAnswer":"Aitysh is a contest where two performers invent spoken or sung poems in response to each other.","supportingFacts":["The performers sit opposite each other and respond to topics chosen by the audience.","They accompany their verses with traditional string instruments."],"revealExplanation":"This tradition in Kazakhstan and Kyrgyzstan values humour, quick thinking and thoughtful ideas.","sources":[{"title":"UNESCO — Aitysh/Aitys, art of improvisation","url":"https://ich.unesco.org/en/RL/aitysh-aitys-art-of-improvisation-00997?RL=00997"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","poetry","central-asia"]},{"id":"bk-culture-017","canonicalKnowledgeId":"bk-culture-017","locale":"en","term":"Táncház","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Dance tradition","A writing tool","A food dish"],"secretAnswer":"Táncház is a Hungarian way of learning folk dance and music through active group practice.","supportingFacts":["Learners watch and copy experienced dancers while live music plays.","People can take part regardless of age or previous dance experience."],"revealExplanation":"The name means dance house. Singing lessons and craft activities can also accompany the dancing.","sources":[{"title":"UNESCO — Táncház method: a Hungarian model","url":"https://ich.unesco.org/en/BSP/tanchaz-method-a-hungarian-model-for-the-transmission-of-intangible-cultural-heritage-00515"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","hungary","dance"]},{"id":"bk-culture-018","canonicalKnowledgeId":"bk-culture-018","locale":"en","term":"Bourdaloue vessel","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A bourdaloue is an oval portable chamber pot designed for a woman to use.","supportingFacts":["Examples could be made from decorated porcelain.","The Holburne Museum's example was made at the Meissen factory."],"revealExplanation":"One museum example was altered after damage and may later have been mistaken for a plant pot.","sources":[{"title":"The Holburne Museum — Meissen Porcelain Bourdaloue","url":"https://holburne.org/meissen-porcelain-bourdaloue/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","household","porcelain"]},{"id":"bk-culture-019","canonicalKnowledgeId":"bk-culture-019","locale":"en","term":"Stay busk","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Clothing accessory"],"secretAnswer":"A stay busk is a stiff piece placed at the front of a corset to help it keep its shape.","supportingFacts":["The Met has a curved wooden example.","Busks could be decorated with rare wood or mother-of-pearl."],"revealExplanation":"Makers sometimes put great effort into decorating this piece even though it was usually hidden by clothing.","sources":[{"title":"The Met — Busk","url":"https://www.metmuseum.org/art/collection/search/84189"},{"title":"London Museum — Busk, stay busk, scrimshaw","url":"https://www.londonmuseum.org.uk/collections/v/object-71694/busk-stay-busk-scrimshaw/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","clothing","design"]},{"id":"bk-culture-020","canonicalKnowledgeId":"bk-culture-020","locale":"en","term":"Niddy-noddy","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Textile tool","A festival character","A drinking vessel"],"secretAnswer":"A niddy-noddy is a tool for winding yarn into loose bundles called hanks or skeins.","supportingFacts":["Yarn is wound in a figure of eight around crosspieces at its ends.","The Highland museum's example is made of wood."],"revealExplanation":"It helped prepare spun wool for knitting. The museum's old example has darkened after years in peat smoke.","sources":[{"title":"Museum of the Highlands — Crios-iarna or Niddy-noddy","url":"https://museumofthehighlands.org/project/crios-iarna-or-niddy-noddy"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","textiles","tools"]},{"id":"bk-culture-021","canonicalKnowledgeId":"bk-culture-021","locale":"en","term":"Lucet","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A lucet is a small fork-shaped tool used to make braided cord from thread.","supportingFacts":["A typical lucet has two prongs at one end.","Its cord is strong, slightly springy and square in shape."],"revealExplanation":"The basic technique uses one continuous thread; the cord can serve as clothing laces or bag ties.","sources":[{"title":"Hyland House Museum — Build a Lucet Tool and Braid Cords","url":"https://hylandhouse.org/at-home-activities/how-to-make-cording-on-a-lucet-tool/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","textiles","tools"]},{"id":"bk-culture-022","canonicalKnowledgeId":"bk-culture-022","locale":"en","term":"Pounce pot","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Writing equipment"],"secretAnswer":"A pounce pot holds powder that is sprinkled on paper to help prepare it for writing or dry ink.","supportingFacts":["Small holes in its top let the powder fall through.","A shallow dish on top can catch extra powder."],"revealExplanation":"Pounce could be made from materials such as pumice, tree resin or ground cuttlefish bone.","sources":[{"title":"The Village at Black Creek — Pounce Pot","url":"https://blackcreek.ca/exhibits/out-of-the-box-exploring-artifacts/pounce-pot/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","writing","tools"]},{"id":"bk-culture-023","canonicalKnowledgeId":"bk-culture-023","locale":"en","term":"Spill vase","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Historical household object","A language custom","A dance form"],"secretAnswer":"A spill vase stores thin wood strips or rolled paper used to carry a flame to a candle or lamp.","supportingFacts":["These strips or rolls are called spills.","They offered a cheap way to light things when matches were expensive."],"revealExplanation":"The Brunel Museum's example has a flat back so it can stand neatly against a wall on a mantelpiece.","sources":[{"title":"Brunel Museum — Why doesn't this vase have room for flowers?","url":"https://thebrunelmuseum.com/why-doesnt-this-vase-have-room-for-flowers/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","household","lighting"]},{"id":"bk-culture-024","canonicalKnowledgeId":"bk-culture-024","locale":"en","term":"Clog almanac","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A clog almanac is a wooden calendar marked with days and symbols for important dates.","supportingFacts":["Its symbols can mark saints' feast days.","It can also mark important dates in the farming year."],"revealExplanation":"The British Museum holds a Norwegian example with marks for days and weeks.","sources":[{"title":"British Museum — Clog-almanac, 1928,0313.1","url":"https://www.britishmuseum.org/collection/object/H_1928-0313-1"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","calendar","wood"]},{"id":"bk-culture-025","canonicalKnowledgeId":"bk-culture-025","locale":"en","term":"Hornbook","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Learning equipment"],"secretAnswer":"A hornbook is a small handled board that carries a protected sheet for children learning letters and numbers.","supportingFacts":["A thin clear layer of horn, or sometimes mica, protects the printed sheet.","Many sheets also include the Lord's Prayer."],"revealExplanation":"The small board could hang from a child's belt so its lessons stayed close at hand.","sources":[{"title":"Library of Congress — A Child's Introduction to the Alphabet","url":"https://www.loc.gov/exhibitions/treasures-from-the-library-of-congress/about-this-exhibition/guiding-memory/a-childs-introduction-to-the-alphabet/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","reading","education"]},{"id":"bk-culture-026","canonicalKnowledgeId":"bk-culture-026","locale":"en","term":"Syllabub","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Food and drink","A verse form","A weaving tool"],"secretAnswer":"Syllabub is a sweet English treat made by mixing wine with cream or milk to form a light froth.","supportingFacts":["Historical recipes could add sugar and lemon.","Some versions have creamy foam above a layer of wine."],"revealExplanation":"An everlasting syllabub used more cream and less wine, making a thicker dessert.","sources":[{"title":"US National Library of Medicine — Sup on a Syllabub","url":"https://circulatingnow.nlm.nih.gov/2016/12/29/sup-on-a-syllabub/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","food","dessert"]},{"id":"bk-culture-027","canonicalKnowledgeId":"bk-culture-027","locale":"en","term":"Hidden fore-edge painting","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A hidden fore-edge painting is a picture on a book's page edges that appears when the pages are fanned out.","supportingFacts":["The artist paints the pages while they are fanned and held in a clamp.","Gold is applied to the closed edges to hide the picture."],"revealExplanation":"Some books have two hidden pictures, with a different scene revealed when the pages are fanned the other way.","sources":[{"title":"University of Sydney Library — Hidden Fore-edge Paintings","url":"https://www.library.sydney.edu.au/stories/hidden-fore-edge-paintings"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","books","art"]},{"id":"bk-culture-028","canonicalKnowledgeId":"bk-culture-028","locale":"en","term":"Misericord","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Historical church furniture"],"secretAnswer":"A misericord is a small ledge under a folding church seat that supports a person when the seat is raised.","supportingFacts":["It is part of a hinged seat in the choir stalls.","Its underside can carry carved scenes, sometimes with comic or rude subjects."],"revealExplanation":"The Art Fund's Bristol example is carved in oak and shows a joke involving an archer.","sources":[{"title":"Art Fund — Misericord, Bristol Museum & Art Gallery","url":"https://www.artfund.org/our-purpose/art-funded-by-you/misericord"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","furniture","church"]},{"id":"bk-culture-029","canonicalKnowledgeId":"bk-culture-029","locale":"en","term":"Frumenty","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Historical food","A writing tool","A dance step"],"secretAnswer":"Frumenty is a thick dish of wheat cooked in milk or broth.","supportingFacts":["Some versions are sweetened and flavoured with cinnamon.","Its name comes from the Latin word for grain."],"revealExplanation":"A medieval recipe book includes a version served with porpoise, showing how different old menus could be.","sources":[{"title":"Weston Museum — Recipes Through Time: Frumenty","url":"https://westonmuseum.org/recipes-through-time-frumenty/"},{"title":"London Museum — A Sainsbury's history of Christmas pudding","url":"https://www.londonmuseum.org.uk/blog/christmas-pudding-history-sainsburys/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","food","medieval"]},{"id":"bk-culture-030","canonicalKnowledgeId":"bk-culture-030","locale":"en","term":"Mazer","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A mazer is a wooden drinking bowl, often made from maple and fitted with a metal rim.","supportingFacts":["Surviving examples have rims made of silver or silver covered in gold.","Some have words or decorative designs on them."],"revealExplanation":"One bowl in the Met advises its drinker to think a lot and speak less.","sources":[{"title":"Cambridge University Press — On the English medieval drinking bowls called Mazers","url":"https://www.cambridge.org/core/journals/archaeologia/article/abs/xion-the-english-medieval-drinking-bowls-called-mazers/B0579ED83F7E21B3DB31543D258261BB"},{"title":"The Met — Drinking Bowl, 55.25","url":"https://www.metmuseum.org/art/collection/search/471558"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["culture","tableware","wood"]},{"id":"bk-halloween-001","canonicalKnowledgeId":"bk-halloween-001","deck":"halloween","locale":"en","term":"Souling","publicPrompt":"What is this old Halloween custom?","hintMode":"category","publicHints":["Medieval custom"],"secretAnswer":"Souling was a medieval custom: around All Souls’ Day, people went from house to house praying or singing for the dead, and got small “soul cakes” in return.","supportingFacts":["All Souls’ Day is on 2 November.","The prayers were for the people who gave the cakes and for their dead relatives."],"revealExplanation":"Many historians see souling as an early form of trick-or-treating.","sources":[{"title":"English Heritage: No tricks, just treats – try a medieval soul cake","url":"https://www.english-heritage.org.uk/about/search-news/no-tricks-just-treats-try-a-medieval-soul-cake-as-english-heritage-castles-stay-open-after-dark/"},{"title":"Smithsonian Magazine: How Trick-or-Treating Started","url":"https://www.smithsonianmag.com/arts-culture/how-trick-or-treating-started-71619242/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","tradition","medieval","england"]},{"id":"bk-halloween-002","canonicalKnowledgeId":"bk-halloween-002","deck":"halloween","locale":"en","term":"Stingy Jack","publicPrompt":"Who is this, and why is he famous?","hintMode":"choices","publicHints":["Irish folk tale","Pirate legend","Circus story"],"secretAnswer":"Stingy Jack is a man in an Irish folk tale who tricked the Devil. Later neither heaven nor hell would take him, so he wanders in the dark with a coal inside a carved turnip.","supportingFacts":["He tricked the Devil twice: once into turning into a coin, and once into climbing a tree.","People called him “Jack of the Lantern”, which became “jack-o’-lantern”."],"revealExplanation":"Irish and Scottish families carved scary faces into turnips to keep him away, and immigrants later brought the custom to America, the home of the pumpkin.","sources":[{"title":"HISTORY: History of the Jack O’Lantern – Irish Origins","url":"https://www.history.com/articles/history-of-the-jack-o-lantern-irish-origins"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","folklore","ireland","jack-o-lantern"]},{"id":"bk-halloween-003","canonicalKnowledgeId":"bk-halloween-003","deck":"halloween","locale":"en","term":"Punkie Night","publicPrompt":"What is this English village tradition?","hintMode":"none","publicHints":[],"secretAnswer":"Punkie Night is a lantern walk in Hinton St George, Somerset. On the last Thursday of October, children carry candles inside carved root vegetables called mangel-wurzels.","supportingFacts":["A Punkie King and Queen lead the walk, and the children sing the Punkie Song.","One story says village women once made lanterns to look for husbands who got lost coming home from a fair."],"revealExplanation":"Prizes go to the best punkies in each age group.","sources":[{"title":"Calendar Customs: Punkie Night, Hinton St George","url":"https://www.calendarcustoms.com/?p=1428"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","tradition","england","lanterns"]},{"id":"bk-halloween-004","canonicalKnowledgeId":"bk-halloween-004","deck":"halloween","locale":"en","term":"Barmbrack","publicPrompt":"What is this, and why is it special at Halloween?","hintMode":"category","publicHints":["Irish food"],"secretAnswer":"Barmbrack is an Irish fruit loaf baked for Halloween. Small objects are hidden inside, and the one you find tells your future, such as a ring for a wedding within a year.","supportingFacts":["Its Irish name, báirín breac, means “speckled loaf”.","A coin meant good fortune, while a pea meant you would not marry that year."],"revealExplanation":"Today most Halloween bracks contain just a ring or a coin.","sources":[{"title":"Ireland.ie: Báirín Breac, a traditional Irish Halloween recipe","url":"https://api.ireland.ie/en/visit/halloween/bairin-breac-a-traditional-irish-halloween-recipe/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","tradition","ireland","food","fortune-telling"]},{"id":"bk-halloween-005","canonicalKnowledgeId":"bk-halloween-005","deck":"halloween","locale":"en","term":"Snap-Apple Night","publicPrompt":"What is this, and where does the name come from?","hintMode":"choices","publicHints":["Halloween party game","Cider festival","Harvest dance"],"secretAnswer":"Snap-Apple Night was an old name for Halloween. It comes from a party game: players try to bite an apple hanging on a string without using their hands.","supportingFacts":["Irish painter Daniel Maclise painted the game after a Halloween party in Blarney in 1832.","People believed the game could show who would marry next."],"revealExplanation":"The same painting also shows boys bobbing for apples in water.","sources":[{"title":"The Met: Snap Apple Night, or All-Hallow Eve (after Daniel Maclise)","url":"https://www.metmuseum.org/art/collection/search/644100"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","tradition","ireland","games","art"]},{"id":"bk-halloween-006","canonicalKnowledgeId":"bk-halloween-006","deck":"halloween","locale":"en","term":"Burning nuts on Halloween","publicPrompt":"What was this old Scottish custom for?","hintMode":"none","publicHints":[],"secretAnswer":"An engaged couple each put a nut on the fire. If the nuts burned quietly, their marriage would be happy; if they spat and hissed, it would be stormy.","supportingFacts":["Robert Burns wrote about Scottish Halloween customs in his 1785 poem “Halloween”.","In another custom, people pulled up kale stalks in the dark to guess the height and shape of a future partner."],"revealExplanation":"Halloween in Scotland grew from the old Celtic festival of Samhain.","sources":[{"title":"Historic UK: Halloween in Scotland","url":"https://www.historic-uk.com/CultureUK/Halloween-in-Scotland/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","tradition","scotland","fortune-telling"]},{"id":"bk-halloween-007","canonicalKnowledgeId":"bk-halloween-007","deck":"halloween","locale":"en","term":"Guising","publicPrompt":"What is this Scottish Halloween tradition?","hintMode":"choices","publicHints":["Halloween custom","Sword dance","Wedding song"],"secretAnswer":"Guising is the Scottish way of going door to door at Halloween in costume. Children dress up and usually do a small act, like a song or a joke, before they get a treat.","supportingFacts":["Children first dressed as spirits so they could mix in with the spirits thought to walk that night.","Scottish children went guising long before “trick or treat” became common."],"revealExplanation":"Their lanterns were hollowed-out turnips called neep lanterns, not pumpkins.","sources":[{"title":"Historic UK: Halloween in Scotland","url":"https://www.historic-uk.com/CultureUK/Halloween-in-Scotland/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","tradition","scotland","costumes"]},{"id":"bk-halloween-008","canonicalKnowledgeId":"bk-halloween-008","deck":"halloween","locale":"en","term":"Samhain","publicPrompt":"What was this?","hintMode":"category","publicHints":["Ancient festival"],"secretAnswer":"Samhain was an old Celtic festival on 1 November and the evening before. It marked the end of summer, and people believed the line between the living and the dead grew thin.","supportingFacts":["Its Irish name is explained as “summer’s end”.","It partly shaped modern Halloween."],"revealExplanation":"Some modern Pagans, including Wiccans, still celebrate Samhain.","sources":[{"title":"Britannica: Samhain","url":"https://www.britannica.com/topic/Samhain"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","tradition","celtic","festival"]},{"id":"bk-halloween-009","canonicalKnowledgeId":"bk-halloween-009","deck":"halloween","locale":"en","term":"Calaveras literarias","publicPrompt":"What are these?","hintMode":"none","publicHints":[],"secretAnswer":"Calaveras literarias are funny rhyming poems written for Mexico’s Day of the Dead. They joke about living people, often politicians, as if death has come to take them.","supportingFacts":["The name roughly means “skull literature”.","A Mexican newspaper first published them in 1849.","Some were banned or destroyed because of their political jokes."],"revealExplanation":"Today many people post them on social media before the holiday on 1–2 November.","sources":[{"title":"PBS NewsHour: These wicked Day of the Dead poems don’t spare anyone","url":"https://www.pbs.org/newshour/arts/poetry/these-wicked-day-of-the-dead-poems-dont-spare-anyone"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","tradition","mexico","poetry"]},{"id":"bk-halloween-010","canonicalKnowledgeId":"bk-halloween-010","deck":"halloween","locale":"en","term":"La Catrina","publicPrompt":"Who or what is this?","hintMode":"choices","publicHints":["Day of the Dead symbol","Spanish dance","Famous ship"],"secretAnswer":"La Catrina is a skeleton lady in fancy clothes. Mexican artist José Guadalupe Posada first drew her in 1912 to tease people who copied European fashion. She is now a Day of the Dead symbol.","supportingFacts":["Her first name was “Calavera Garbancera”.","Diego Rivera painted her in the middle of his 1947 mural “Dream of a Sunday Afternoon in Alameda Park”."],"revealExplanation":"The name “Catrina” first appeared in a 1930 book of Posada’s prints.","sources":[{"title":"PBS NewsHour: How La Catrina became the iconic symbol for the Day of the Dead","url":"https://www.pbs.org/newshour/amp/arts/how-la-catrina-became-the-iconic-symbol-for-the-day-of-the-dead"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","tradition","mexico","art"]},{"id":"bk-halloween-011","canonicalKnowledgeId":"bk-halloween-011","deck":"halloween","locale":"en","term":"Hyakumonogatari Kaidankai","publicPrompt":"What is this Japanese tradition?","hintMode":"category","publicHints":["Storytelling game"],"secretAnswer":"It is an old Japanese ghost-story game. People light 100 candles, and after each spooky story they blow one out, so the room gets darker and darker.","supportingFacts":["It was played in the Edo period, said to be a way for young samurai to show courage.","People believed a spirit might appear when the last candle went out."],"revealExplanation":"A full modern game can take about four hours, and placing 100 candles safely is the hardest part.","sources":[{"title":"Horror Writers Association: Hyaku Monogatari Kaidankai – why not tell a hundred scary stories","url":"https://horror.org/hyaku-monogatari-kaidankai-or-this-halloween-why-not-tell-a-hundred-scary-stories-in-the-growing-dark-by-kevin-j-wetmore-jr/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","tradition","japan","storytelling"]},{"id":"bk-halloween-012","canonicalKnowledgeId":"bk-halloween-012","deck":"halloween","locale":"en","term":"The ravens of the Tower of London","publicPrompt":"What is the old legend?","hintMode":"none","publicHints":[],"secretAnswer":"Legend says the kingdom and the Tower will fall if the ravens ever leave. King Charles II is said to have ordered that at least six ravens be kept there at all times.","supportingFacts":["A Ravenmaster looks after them, and they respond only to the Ravenmaster.","Charles II’s astronomer, John Flamsteed, complained that the birds got in the way of his work."],"revealExplanation":"The story about Charles II is a tradition, not proven history.","sources":[{"title":"Historic Royal Palaces: The ravens of the Tower of London","url":"https://www.hrp.org.uk/tower-of-london/explore/the-ravens/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","place","london","legend"]},{"id":"bk-halloween-013","canonicalKnowledgeId":"bk-halloween-013","deck":"halloween","locale":"en","term":"Whitby Abbey","publicPrompt":"Why is this place famous at Halloween?","hintMode":"choices","publicHints":["Famous novel","Royal wedding","Sea battle"],"secretAnswer":"The ruins of Whitby Abbey in England helped inspire Bram Stoker’s “Dracula”. He visited Whitby on holiday in 1890 and set part of the story there.","supportingFacts":["In Whitby’s library, Stoker read about Vlad Tepes, a ruler known as Dracula.","In the novel, Dracula arrives on a ship that runs aground, and a large dog runs up the 199 steps."],"revealExplanation":"The book Stoker found said that “Dracula” in the Wallachian language means “devil”.","sources":[{"title":"English Heritage: Whitby Abbey and Dracula","url":"https://www.english-heritage.org.uk/visit/places/whitby-abbey/history-and-stories/dracula"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","place","england","literature"]},{"id":"bk-halloween-014","canonicalKnowledgeId":"bk-halloween-014","deck":"halloween","locale":"en","term":"The Bodie curse","publicPrompt":"What is this story?","hintMode":"category","publicHints":["Ghost town legend"],"secretAnswer":"People say anyone who takes even a small rock from Bodie, a California ghost town, will get bad luck. About once a week, visitors mail items back with “sorry” letters.","supportingFacts":["The story was most likely started by a park ranger to stop people taking things.","Staff must file a report for every returned item, so they no longer promote the curse."],"revealExplanation":"Bodie has been a state park since 1962, and staff say everything there should be left in place.","sources":[{"title":"KQED: How this ghost town’s curse backfired on park rangers","url":"https://kqed.org/news/11640709/how-this-ghost-towns-curse-backfired-on-park-rangers"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","place","usa","legend"]},{"id":"bk-halloween-015","canonicalKnowledgeId":"bk-halloween-015","deck":"halloween","locale":"en","term":"The Flying Dutchman","publicPrompt":"What is the legend?","hintMode":"choices","publicHints":["Sailors’ legend","Circus act","Dutch painting"],"secretAnswer":"The Flying Dutchman is a ghost ship from sailors’ legends, doomed to sail forever. In the best-known version, its captain made a reckless vow to sail around the Cape of Good Hope in a storm.","supportingFacts":["Sailors believed that seeing the ship meant disaster was coming.","Richard Wagner turned the legend into an opera in 1843."],"revealExplanation":"In another version, a captain named Falkenberg sails the North Sea forever, playing dice with the devil.","sources":[{"title":"Britannica: Flying Dutchman","url":"https://www.britannica.com/topic/Flying-Dutchman"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","legend","sea","ghost-ship"]},{"id":"bk-halloween-016","canonicalKnowledgeId":"bk-halloween-016","deck":"halloween","locale":"en","term":"The Mary Celeste","publicPrompt":"What happened?","hintMode":"none","publicHints":[],"secretAnswer":"In 1872 the ship Mary Celeste was found drifting in the Atlantic with nobody on board. It could still sail and had food and water, but its lifeboat and all 10 people were gone.","supportingFacts":["The captain had his wife and two-year-old daughter with him.","It carried 1,701 barrels of industrial alcohol, and most of the cargo was still there."],"revealExplanation":"An 1884 story by Arthur Conan Doyle kept the mystery alive. The 10 people were never found.","sources":[{"title":"Smithsonian Magazine: Abandoned Ship – The Mary Celeste","url":"https://www.smithsonianmag.com/history/abandoned-ship-the-mary-celeste-174488104/"},{"title":"Britannica: Mary Celeste","url":"https://www.britannica.com/topic/Mary-Celeste"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","true-story","sea","mystery"]},{"id":"bk-halloween-017","canonicalKnowledgeId":"bk-halloween-017","deck":"halloween","locale":"en","term":"CROATOAN","publicPrompt":"What is the story behind this word?","hintMode":"choices","publicHints":["Colonial mystery","Pirate password","Magic spell"],"secretAnswer":"CROATOAN was carved on a post at the English colony of Roanoke. When its governor returned in 1590, all the settlers had vanished, and that word was the only clue.","supportingFacts":["The colony was founded in 1587, and governor John White sailed back to England for supplies.","His return was delayed by the Spanish Armada.","The letters “CRO” were also carved on a tree."],"revealExplanation":"The mystery of the “Lost Colony” has never been solved.","sources":[{"title":"Britannica: Lost Colony","url":"https://www.britannica.com/place/Lost-Colony"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","true-story","usa","mystery"]},{"id":"bk-halloween-018","canonicalKnowledgeId":"bk-halloween-018","deck":"halloween","locale":"en","term":"The Brown Lady of Raynham Hall","publicPrompt":"Why is she famous?","hintMode":"none","publicHints":[],"secretAnswer":"The Brown Lady is a ghost said to haunt Raynham Hall in England. In 1936, photographers for Country Life magazine took a famous picture of a veiled figure on the main staircase.","supportingFacts":["People say she is Lady Dorothy Walpole, who lived there in the 1700s.","The picture has been called probably the most famous example of “spirit photography”."],"revealExplanation":"The photo was taken on 19 September 1936 and printed that December.","sources":[{"title":"Country Life: The day a Country Life photographer captured an image of a ghost","url":"https://www.countrylife.co.uk/nature/the-day-a-country-life-photographer-captured-an-image-of-a-ghost-234642"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","place","england","photography"]},{"id":"bk-halloween-019","canonicalKnowledgeId":"bk-halloween-019","deck":"halloween","locale":"en","term":"Borley Rectory","publicPrompt":"Why is this place famous?","hintMode":"choices","publicHints":["Haunted house","Royal school","Shipwreck"],"secretAnswer":"Borley Rectory was a house in Essex once called “the most haunted house in England”. Ghost hunter Harry Price made it famous with stories of a ghostly nun and strange events.","supportingFacts":["Price rented the house in 1937 and brought in 48 helpers to watch for ghosts.","The house was badly damaged by fire in 1939, when an oil lamp fell over."],"revealExplanation":"In 1956 a Society for Psychical Research report argued that the events had ordinary explanations.","sources":[{"title":"Psi Encyclopedia (Society for Psychical Research): Borley Rectory","url":"https://psi-encyclopedia.spr.ac.uk/articles/borley-rectory"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","place","england","ghost-hunting"]},{"id":"bk-halloween-020","canonicalKnowledgeId":"bk-halloween-020","deck":"halloween","locale":"en","term":"The Winchester Mystery House","publicPrompt":"What is strange about this house?","hintMode":"none","publicHints":[],"secretAnswer":"Sarah Winchester, widow of a rifle maker, kept building this house in San Jose, California, for 38 years. It has stairs that end at the ceiling and doors that open onto nothing.","supportingFacts":["A legend says a psychic told her to keep building to keep away spirits connected to the family’s rifles.","The house has about 160 rooms."],"revealExplanation":"Building stopped only when she died in 1922.","sources":[{"title":"NBC Bay Area: The Winchester Mystery House","url":"https://www.nbcbayarea.com/news/local/the-winchester-mystery-house/1910101/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","place","usa","architecture"]},{"id":"bk-halloween-021","canonicalKnowledgeId":"bk-halloween-021","deck":"halloween","locale":"en","term":"Room 217 at the Stanley Hotel","publicPrompt":"Why is this hotel room famous?","hintMode":"choices","publicHints":["Horror novel","Presidential visit","Music video"],"secretAnswer":"Stephen King stayed in Room 217 of the Stanley Hotel in Colorado in 1974, when he and his wife were the only guests. A nightmare there gave him the idea for “The Shining”.","supportingFacts":["The hotel was closing for the winter the next day.","Stanley Kubrick’s 1980 film was not shot at the Stanley, but the 1997 TV miniseries was."],"revealExplanation":"In the novel, the main character also stays in Room 217.","sources":[{"title":"Mental Floss: The real hotel that inspired The Shining","url":"https://www.mentalfloss.com/literature/books/real-hotel-that-inspired-the-shining"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","true-story","usa","literature"]},{"id":"bk-halloween-022","canonicalKnowledgeId":"bk-halloween-022","deck":"halloween","locale":"en","term":"Annie’s room in Mary King’s Close","publicPrompt":"Why do visitors leave toys here?","hintMode":"none","publicHints":[],"secretAnswer":"In 1992 a Japanese psychic visiting this old underground street in Edinburgh said she met the ghost of a little girl named Annie, and gave her a doll. Visitors now bring toys to Annie’s room.","supportingFacts":["The guides admit there is no actual record of a girl called Annie.","Money left in the room goes to a children’s hospital and has raised over £45,000."],"revealExplanation":"The room now holds a pile of dolls, stuffed animals and other gifts.","sources":[{"title":"The Scotsman: Edinburgh’s most haunted – abandoned Annie","url":"https://www.scotsman.com/news/edinburghs-most-haunted-abandoned-annie-1522264"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","place","scotland","true-story"]},{"id":"bk-halloween-023","canonicalKnowledgeId":"bk-halloween-023","deck":"halloween","locale":"en","term":"Bran Castle","publicPrompt":"Why do tourists call this castle by another name?","hintMode":"choices","publicHints":["Vampire novel link","Royal wedding","Famous battle"],"secretAnswer":"Bran Castle in Romania is popularly called “Dracula’s Castle” because it looks like the castle in Bram Stoker’s novel. But Stoker is not known to have visited, and Vlad Dracula never ruled it.","supportingFacts":["In 1920 the castle was given to Queen Marie of Romania, who made it a summer home.","It opened to the public as a museum in 1956."],"revealExplanation":"Some sources say Vlad III was held prisoner there for two months.","sources":[{"title":"Britannica: Bran Castle","url":"https://www.britannica.com/topic/Bran-Castle"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","place","romania","literature"]},{"id":"bk-halloween-024","canonicalKnowledgeId":"bk-halloween-024","deck":"halloween","locale":"en","term":"Púca","publicPrompt":"What is this creature?","hintMode":"category","publicHints":["Irish folklore"],"secretAnswer":"A púca is a shape-shifting spirit in Irish folklore. It often appears as a black horse with flaming eyes and takes people on a wild ride through the night.","supportingFacts":["It can also become a goat, a cat, a dog, a fox or a hare.","When wild berries shrivelled after Samhain, people said the púca had spat on them."],"revealExplanation":"November 1st is said to be the one day a year when the púca behaves politely.","sources":[{"title":"Wilderness Ireland: Irish folklore – the púca","url":"https://www.wildernessireland.com/blog/irish-folklore-puca/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","folklore","ireland","creatures"]},{"id":"bk-halloween-025","canonicalKnowledgeId":"bk-halloween-025","deck":"halloween","locale":"en","term":"Ichabod Crane","publicPrompt":"Who is this?","hintMode":"choices","publicHints":["Ghost story character","American president","Dutch painter"],"secretAnswer":"Ichabod Crane is the nervous schoolteacher in Washington Irving’s 1820 story “The Legend of Sleepy Hollow”. One night he is chased by the Headless Horseman, and then he disappears.","supportingFacts":["Locals say the Horseman is the ghost of a soldier who lost his head to a cannonball and rides at night looking for it.","The next morning, people find Ichabod’s hat with a smashed pumpkin beside it."],"revealExplanation":"The story hints that his rival in love, Brom Bones, knew more than he admitted.","sources":[{"title":"Project Gutenberg: The Legend of Sleepy Hollow by Washington Irving","url":"https://www.gutenberg.org/cache/epub/41/pg41-images.html"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","literature","usa","ghost-story"]},{"id":"bk-halloween-026","canonicalKnowledgeId":"bk-halloween-026","deck":"halloween","locale":"en","term":"Will-o’-the-wisp","publicPrompt":"What is this?","hintMode":"choices","publicHints":["Strange light","Bird call","Fishing trick"],"secretAnswer":"A will-o’-the-wisp is a mysterious light seen flickering over marshes at night. When people walk toward it, it seems to move away and stay out of reach.","supportingFacts":["Its Latin name, ignis fatuus, means “foolish fire”.","Scientists usually explain it as marsh gas from rotting plants catching fire by itself."],"revealExplanation":"One old legend says it is a soul shut out of hell, wandering with its own coal, much like Stingy Jack.","sources":[{"title":"Britannica: Will-o’-the-wisp","url":"https://www.britannica.com/print/article/298712"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","folklore","nature","lights"]},{"id":"bk-halloween-027","canonicalKnowledgeId":"bk-halloween-027","deck":"halloween","locale":"en","term":"Zashiki-warashi","publicPrompt":"What is this?","hintMode":"category","publicHints":["Japanese folklore"],"secretAnswer":"A zashiki-warashi is a child spirit from Japanese folk tales that lives inside a house. A family with one is said to grow rich, but if it leaves, their luck may fall.","supportingFacts":["The best-known stories come from Tōno, in Iwate in northern Japan.","People describe it as a boy, as two girls, or only as sounds like rustling paper."],"revealExplanation":"The book “Tōno Monogatari” says a home where it lives “may enjoy wealth and distinction”.","sources":[{"title":"Yokai.jp: Zashiki-warashi","url":"https://yokai.jp/en/yokai/zashiki-warashi"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","folklore","japan","creatures"]},{"id":"bk-halloween-028","canonicalKnowledgeId":"bk-halloween-028","deck":"halloween","locale":"en","term":"Tsukumogami","publicPrompt":"What are these?","hintMode":"none","publicHints":[],"secretAnswer":"In Japanese folklore, tsukumogami are everyday objects, like umbrellas, sandals or lanterns, that come alive after 100 years, often because they were neglected or thrown away.","supportingFacts":["A sandal spirit called bakezōri wanders the house at night making noise and causing mischief.","The stories teach people to take care of their belongings."],"revealExplanation":"Items that can no longer be repaired may be blessed at a shrine, to stop new tsukumogami from forming.","sources":[{"title":"Museum der Dinge: Tsukumogami – Bakezōri, spirit of a discarded sandal","url":"https://museumderdinge.org/thing-of-the-month/tsukumogami-bakezori-spirit-of-a-discarded-sandal/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","folklore","japan","objects"]},{"id":"bk-halloween-029","canonicalKnowledgeId":"bk-halloween-029","deck":"halloween","locale":"en","term":"The Golem of Prague","publicPrompt":"What is the legend?","hintMode":"choices","publicHints":["Jewish legend","Clock tower story","Castle ghost"],"secretAnswer":"Legend says Rabbi Loew made a giant figure from river clay to protect Prague’s Jewish community. A holy word called a shem, placed in its mouth, brought it to life.","supportingFacts":["When the rabbi forgot to remove the shem before the Sabbath, the Golem ran wild until he took it out.","Its remains are said to lie in the attic of the Old New Synagogue."],"revealExplanation":"The clay was said to come from the Vltava River, and the Golem was called Yossele.","sources":[{"title":"Prague City Tourism: The legend of the Golem","url":"https://prague.eu/en/golem-of-prague/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","folklore","prague","legend"]},{"id":"bk-halloween-030","canonicalKnowledgeId":"bk-halloween-030","deck":"halloween","locale":"en","term":"Baba Yaga","publicPrompt":"Who is she?","hintMode":"category","publicHints":["Slavic folklore"],"secretAnswer":"Baba Yaga is a witch from Slavic folk tales. She lives in a forest hut that turns around on bird legs, and she flies through the air in a mortar, steering with a pestle.","supportingFacts":["She is said to live with two or three sisters who share her name.","She is also said to guard the springs of the water of life."],"revealExplanation":"As she flies, she is said to stir up storms.","sources":[{"title":"Britannica: Baba Yaga","url":"https://www.britannica.com/print/article/47337"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","folklore","slavic","witches"]},{"id":"bk-halloween-031","canonicalKnowledgeId":"bk-halloween-031","deck":"halloween","locale":"en","term":"Kelpie","publicPrompt":"What is this?","hintMode":"choices","publicHints":["Scottish folklore","Wool sweater","Sailing boat"],"secretAnswer":"A kelpie is a shape-shifting water spirit in Scottish folklore. It often looks like a black horse and lives in lochs and rivers, where in many tales it tries to lure people into the water.","supportingFacts":["It can also take human form.","Two 30-metre horse-head sculptures called The Kelpies stand near Falkirk, Scotland."],"revealExplanation":"Artist Andy Scott’s sculpture honours the working horses that once pulled boats along the canal.","sources":[{"title":"Art UK: Andy Scott’s The Kelpies","url":"https://artuk.org/discover/stories/andy-scotts-the-kelpies"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","folklore","scotland","creatures"]},{"id":"bk-halloween-032","canonicalKnowledgeId":"bk-halloween-032","deck":"halloween","locale":"en","term":"St. Elmo’s fire","publicPrompt":"What is this?","hintMode":"choices","publicHints":["Glowing electricity","Church festival","Sailors’ dance"],"secretAnswer":"St. Elmo’s fire is a blue or violet glow that appears on pointed things, like ship masts, during storms. Strong electricity in the air makes the air itself glow.","supportingFacts":["It is named after St Erasmus, also called St Elmo, the protector of Mediterranean sailors.","Sailors saw it as a good sign that the saint was protecting them."],"revealExplanation":"Pilots can see it on wingtips and windshields when flying near thunderstorms.","sources":[{"title":"Geographical: St Elmo’s fire explained","url":"https://geographical.co.uk/news/phenomena-st-elmos-fire-explained"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","science","sea","lights"]},{"id":"bk-halloween-033","canonicalKnowledgeId":"bk-halloween-033","deck":"halloween","locale":"en","term":"Foxfire","publicPrompt":"What is this?","hintMode":"none","publicHints":[],"secretAnswer":"Foxfire is a cool blue-green glow made by fungi growing on rotting wood. In the dark, it can look as if the wood itself is gently shining.","supportingFacts":["It was once also called “fairy fire”.","In the late 1700s, foxfire lit the instruments of the Turtle, an early one-person submarine."],"revealExplanation":"More than 75 kinds of glowing fungi are known today.","sources":[{"title":"Nature Stories: Burning with cold fire","url":"https://naturestories.org/burning-with-cold-fire"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","science","nature","lights"]},{"id":"bk-halloween-034","canonicalKnowledgeId":"bk-halloween-034","deck":"halloween","locale":"en","term":"Vic Tandy’s laboratory ghost","publicPrompt":"What was the real cause?","hintMode":"none","publicHints":[],"secretAnswer":"Researcher Vic Tandy felt a ghostly presence in his lab. He traced it to a faulty fan making a very low sound, about 19 hertz, too low to hear. With the fan off, the “ghost” was gone.","supportingFacts":["He later measured the same 19-hertz sound in a “haunted” 14th-century cellar in Coventry.","With the fan off, the room changed from “enclosed, muggy” to pleasant."],"revealExplanation":"Tandy suggested that this kind of sound might explain some ghost sightings.","sources":[{"title":"Times Higher Education: report on Vic Tandy’s infrasound ghost research","url":"https://www.timeshighereducation.com/node/27482"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","science","sound","true-story"]},{"id":"bk-halloween-035","canonicalKnowledgeId":"bk-halloween-035","deck":"halloween","locale":"en","term":"Pepper’s ghost","publicPrompt":"What is this?","hintMode":"choices","publicHints":["Stage illusion","Cooking story","Pirate legend"],"secretAnswer":"Pepper’s ghost is a stage trick that makes a see-through “ghost” appear. A hidden, brightly lit actor is reflected in a sheet of glass that the audience does not notice.","supportingFacts":["John Henry Pepper showed it at Christmas 1862 in a play based on a Charles Dickens story.","It needs only an actor, a light and a sheet of glass."],"revealExplanation":"Museums and theme parks around the world still use it.","sources":[{"title":"Indiana Public Media, A Moment of Science: How to see ghosts with Pepper’s ghost illusion","url":"https://www.ipm.org/show/amomentofscience/2023-04-11/how-to-see-ghosts-with-peppers-ghost-illusion"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","history","theatre","illusion"]},{"id":"bk-halloween-036","canonicalKnowledgeId":"bk-halloween-036","deck":"halloween","locale":"en","term":"Phantasmagoria","publicPrompt":"What was this?","hintMode":"choices","publicHints":["Ghost show","Garden maze","Sweet pastry"],"secretAnswer":"Phantasmagoria was a ghost show in Paris in the 1790s. Showman Étienne-Gaspard Robertson used a magic lantern on wheels to make ghosts seem to rush toward the audience through smoke.","supportingFacts":["The shows took place in an old, empty convent near Place Vendôme.","Some people believed the ghosts were real, and the authorities first shut the show down."],"revealExplanation":"These shows helped shape horror theatre and, later, the cinema.","sources":[{"title":"Atlas Obscura: Robertson’s Fantastic Phantasmagoria","url":"https://www.atlasobscura.com/articles/robertsons-fantastic-phantasmagoria"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","history","paris","illusion"]},{"id":"bk-halloween-037","canonicalKnowledgeId":"bk-halloween-037","deck":"halloween","locale":"en","term":"The Fox sisters","publicPrompt":"Why are they famous?","hintMode":"none","publicHints":[],"secretAnswer":"In 1848 two young sisters in Hydesville, New York, said a spirit was talking to them through rapping sounds. Their story helped start Spiritualism, a movement about contacting the dead.","supportingFacts":["The sisters, Maggie and Kate, were 14 and 11.","In 1888 Maggie showed how she made the raps by cracking her toe joints."],"revealExplanation":"Maggie said the rapping was “simply the result of perfect control of the muscles of the leg below the knee”.","sources":[{"title":"Girl Museum: The curious Fox sisters","url":"https://www.girlmuseum.org/the-curious-fox-sisters/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","history","usa","true-story"]},{"id":"bk-halloween-038","canonicalKnowledgeId":"bk-halloween-038","deck":"halloween","locale":"en","term":"The Houdini séance","publicPrompt":"What was this?","hintMode":"choices","publicHints":["Halloween promise","Magic contest","Prison escape"],"secretAnswer":"Harry Houdini died on Halloween in 1926. He and his wife Bess had agreed on a secret code, so she held a séance every Halloween to see if he would send it. After ten years, she stopped.","supportingFacts":["Their secret code began with the word “Rosabelle”.","The last séance, in 1936, was held on a Hollywood hotel roof and broadcast on radio."],"revealExplanation":"Bess later said, “10 years is long enough to wait for any man.”","sources":[{"title":"Library of Congress Blog: Hollywood, Houdini and the Halloween séance of 1936","url":"https://blogs.loc.gov/loc/2020/10/hollywood-houdini-and-the-halloween-seance-of-1936/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","history","usa","true-story"]},{"id":"bk-halloween-039","canonicalKnowledgeId":"bk-halloween-039","deck":"halloween","locale":"en","term":"The Ghost Club","publicPrompt":"What is this?","hintMode":"category","publicHints":["London society"],"secretAnswer":"The Ghost Club is a society started in London in 1862 to study ghosts and strange events. Charles Dickens was one of its early members.","supportingFacts":["It calls itself the oldest group in the world linked to psychical research.","Members hold overnight investigations, and Ouija boards are not allowed."],"revealExplanation":"Its roots go back to Trinity College, Cambridge, where fellows began discussing ghosts in 1855.","sources":[{"title":"The Ghost Club: History","url":"https://ghostclub.org.uk/history.html"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","history","london","ghost-hunting"]},{"id":"bk-halloween-040","canonicalKnowledgeId":"bk-halloween-040","deck":"halloween","locale":"en","term":"The Surgeon’s Photograph","publicPrompt":"What is the story behind this picture?","hintMode":"none","publicHints":[],"secretAnswer":"The Surgeon’s Photograph, from 1934, seemed to show the Loch Ness Monster. Sixty years later, a man confessed it was really a toy submarine with a model sea-serpent head.","supportingFacts":["A respected surgeon, Colonel Robert Wilson, was used as the photographer to make it believable.","The plan came from Marmaduke Wetherell, who wanted revenge after his fake “monster” footprints were exposed."],"revealExplanation":"Christian Spurling, who built the model, confessed in 1994 at the age of 90.","sources":[{"title":"The Museum of Hoaxes: The Surgeon’s Photo","url":"https://hoaxes.org/photo_database/image/the_surgeons_photo/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","history","scotland","hoax"]},{"id":"bk-halloween-041","canonicalKnowledgeId":"bk-halloween-041","deck":"halloween","locale":"en","term":"The Villa Diodati ghost-story contest","publicPrompt":"What happened here?","hintMode":"choices","publicHints":["Writers’ challenge","Chess match","Royal ball"],"secretAnswer":"In 1816, bad weather kept Lord Byron, Mary Shelley and friends inside a villa near Lake Geneva. Byron challenged everyone to write a scary story, and Mary Shelley’s became “Frankenstein”.","supportingFacts":["1816 is called the “Year Without a Summer” because a volcanic eruption in 1815 cooled the world.","Byron’s doctor, John Polidori, wrote “The Vampyre” for the same challenge."],"revealExplanation":"Byron gave up on his own story, which was later published without his permission.","sources":[{"title":"JSTOR: Frankenstein, The Vampyre, and echoes from the summer of 1816","url":"https://about.jstor.org/blog/frankenstein-the-vampyre-and-the-spirit-of-the-humanities-echoes-from-the-summer-of-1816"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","literature","switzerland","true-story"]},{"id":"bk-halloween-042","canonicalKnowledgeId":"bk-halloween-042","deck":"halloween","locale":"en","term":"The Canterville Ghost","publicPrompt":"What is this story about?","hintMode":"choices","publicHints":["Funny ghost story","War poem","Detective case"],"secretAnswer":"“The Canterville Ghost” is a funny story by Oscar Wilde. An American family moves into a haunted English castle and refuses to be scared, answering the ghost’s tricks with practical fixes like stain remover.","supportingFacts":["The ghost, Sir Simon de Canterville, becomes more and more embarrassed.","Only the young daughter, Virginia, understands that he needs peace."],"revealExplanation":"The story first appeared in 1887.","sources":[{"title":"Project Gutenberg: The Canterville Ghost by Oscar Wilde","url":"https://gutenberg.org/ebooks/14522"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","literature","england","ghost-story"]},{"id":"bk-halloween-043","canonicalKnowledgeId":"bk-halloween-043","deck":"halloween","locale":"en","term":"Mothman","publicPrompt":"Who or what is this?","hintMode":"category","publicHints":["West Virginia legend"],"secretAnswer":"Mothman is a creature reported in Point Pleasant, West Virginia, in November 1966. Two couples said they saw a man-sized flying figure with huge wings and glowing red eyes.","supportingFacts":["The town has a Mothman statue and a Mothman Museum, opened in 2006.","Its yearly Mothman Festival in September draws more visitors than the town’s population."],"revealExplanation":"The local newspaper’s headline read: “Couples See Man-Sized Bird… Creature… Something.”","sources":[{"title":"Legends of America: The Mothman of West Virginia","url":"https://www.legendsofamerica.com/west-virginia-mothman/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","legend","usa","creatures"]},{"id":"bk-halloween-044","canonicalKnowledgeId":"bk-halloween-044","deck":"halloween","locale":"en","term":"The Marfa lights","publicPrompt":"What are these?","hintMode":"choices","publicHints":["Mystery lights","Desert festival","Star map"],"secretAnswer":"The Marfa lights are small yellow-white lights that people watch for at night near Marfa, a small town in West Texas. They move slowly and flicker, and they draw many visitors.","supportingFacts":["After months of watching, engineering professor Karl Stephan concluded that most of them are car headlights about two dozen miles away.","Local folklore also includes stories of witches who turn into owls."],"revealExplanation":"Stephan says a rarer kind is harder to explain, because “you can’t prove a negative”.","sources":[{"title":"NBC DFW: Texas Wants to Know – what’s behind the Marfa lights?","url":"https://www.nbcdfw.com/news/local/texas-news/texas-wants-to-know-whats-behind-the-marfa-lights/3211889/"}],"verificationStatus":"verified","verifiedAt":"2026-10-24","enabled":true,"tags":["halloween","legend","usa","lights"]},{"id":"bk-nature-001","canonicalKnowledgeId":"bk-nature-001","locale":"en","term":"Virga","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Weather"],"secretAnswer":"Virga is rain or snow that falls from a cloud but disappears before reaching the ground.","supportingFacts":["Dry air below the cloud makes the falling water disappear into the air.","It can look like thin tails hanging from a cloud."],"revealExplanation":"The disappearing water cools the air around it.","sources":[{"title":"NOAA National Weather Service: Owlie's Weird Weather","url":"https://www.weather.gov/owlie/weird-weather"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["weather","precipitation"]},{"id":"bk-nature-002","canonicalKnowledgeId":"bk-nature-002","locale":"en","term":"Snow roller","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Weather","Animal behavior","Food"],"secretAnswer":"A snow roller is a roll of snow formed naturally by wind or by rolling downhill.","supportingFacts":["The snow must be sticky enough to hold together.","Strong wind can break the roll apart."],"revealExplanation":"Some rollers have a hollow middle and look like doughnuts.","sources":[{"title":"NOAA National Weather Service: Owlie's Weird Weather","url":"https://www.weather.gov/owlie/weird-weather"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["weather","snow"]},{"id":"bk-nature-003","canonicalKnowledgeId":"bk-nature-003","locale":"en","term":"Hair ice","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"Hair ice is a mass of very thin ice threads that grows on dead wood with help from a fungus.","supportingFacts":["It can form on cold, damp nights.","Chemicals from the fungus help keep the ice in thin strands."],"revealExplanation":"It often melts in the morning.","sources":[{"title":"NOAA National Weather Service: Owlie's Weird Weather","url":"https://www.weather.gov/owlie/weird-weather"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["ice","fungus"]},{"id":"bk-nature-004","canonicalKnowledgeId":"bk-nature-004","locale":"en","term":"Lenticular cloud","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Weather"],"secretAnswer":"A lenticular cloud is a lens-shaped cloud formed in waves of air, often behind mountains.","supportingFacts":["Moist air rises in a standing wave and forms the cloud.","Its shape can look like a flying saucer."],"revealExplanation":"The air nearby can be rough for aircraft.","sources":[{"title":"Met Office: Unusual cloud formations","url":"https://weather.metoffice.gov.uk/learn-about/weather/types-of-weather/clouds/unusual-cloud-formations"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["weather","clouds"]},{"id":"bk-nature-005","canonicalKnowledgeId":"bk-nature-005","locale":"en","term":"Nacreous cloud","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Weather","Jewelry","Sea life"],"secretAnswer":"A nacreous cloud is a very high cloud that shines with pearl-like colors near sunrise or sunset.","supportingFacts":["It forms in the lower stratosphere over polar regions.","Its small ice particles scatter light."],"revealExplanation":"Sunlight can still reach it when the sun is below the horizon.","sources":[{"title":"Met Office: Unusual cloud formations","url":"https://weather.metoffice.gov.uk/learn-about/weather/types-of-weather/clouds/unusual-cloud-formations"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["weather","clouds"]},{"id":"bk-nature-006","canonicalKnowledgeId":"bk-nature-006","locale":"en","term":"Noctilucent cloud","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A noctilucent cloud is a very high cloud of ice crystals that can still shine after sunset.","supportingFacts":["It is in the mesosphere, above ordinary clouds.","Its great height lets it keep reflecting sunlight."],"revealExplanation":"These clouds are too high to change weather on the ground.","sources":[{"title":"Met Office: Unusual cloud formations","url":"https://weather.metoffice.gov.uk/learn-about/weather/types-of-weather/clouds/unusual-cloud-formations"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["weather","clouds"]},{"id":"bk-nature-007","canonicalKnowledgeId":"bk-nature-007","locale":"en","term":"Mammatus","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Weather"],"secretAnswer":"Mammatus are rounded, pouch-like shapes hanging from the underside of a cloud.","supportingFacts":["They often appear below a large thunderstorm cloud.","They can also appear on other types of cloud."],"revealExplanation":"Their name comes from a Latin word for an udder or breast.","sources":[{"title":"Met Office: Unusual cloud formations","url":"https://weather.metoffice.gov.uk/learn-about/weather/types-of-weather/clouds/unusual-cloud-formations"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["weather","clouds"]},{"id":"bk-nature-008","canonicalKnowledgeId":"bk-nature-008","locale":"en","term":"Brocken spectre","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Light and vision","Folklore","Sea life"],"secretAnswer":"A Brocken spectre is a person's shadow on mist or cloud that appears like a huge distant figure.","supportingFacts":["The sun is behind the person.","People often see it from mountain tops."],"revealExplanation":"It was named after a mountain in Germany.","sources":[{"title":"Met Office: Optical effects","url":"https://weather.metoffice.gov.uk/learn-about/weather/optical-effects"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["light","weather"]},{"id":"bk-nature-009","canonicalKnowledgeId":"bk-nature-009","locale":"en","term":"Parhelion","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A parhelion is a bright spot beside the sun caused by sunlight passing through ice crystals.","supportingFacts":["The crystals have six sides.","These spots are also called sun dogs."],"revealExplanation":"They can appear with a ring of light around the sun.","sources":[{"title":"Met Office: Optical effects","url":"https://weather.metoffice.gov.uk/learn-about/weather/optical-effects"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["light","weather"]},{"id":"bk-nature-010","canonicalKnowledgeId":"bk-nature-010","locale":"en","term":"Circumzenithal arc","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Light and vision"],"secretAnswer":"A circumzenithal arc is a colored arc in the sky that looks like an upside-down rainbow.","supportingFacts":["Sunlight passes through flat ice crystals.","Lower clouds can hide the arc."],"revealExplanation":"The crystals bend light rather than raindrops making a rainbow.","sources":[{"title":"Met Office: Optical effects","url":"https://weather.metoffice.gov.uk/learn-about/weather/optical-effects"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["light","weather"]},{"id":"bk-nature-011","canonicalKnowledgeId":"bk-nature-011","locale":"en","term":"Fogbow","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Light and vision","Sea navigation","Food"],"secretAnswer":"A fogbow is a pale, often almost white bow of light made by tiny water drops in fog or mist.","supportingFacts":["Its water drops are smaller than raindrops.","It is wider than a typical rainbow."],"revealExplanation":"The tiny drops spread the colors so they are hard to see.","sources":[{"title":"Met Office: Rainbows","url":"https://weather.metoffice.gov.uk/learn-about/weather/optical-effects/rainbows"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["light","weather"]},{"id":"bk-nature-012","canonicalKnowledgeId":"bk-nature-012","locale":"en","term":"Moonbow","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A moonbow is a rainbow made by moonlight instead of sunlight.","supportingFacts":["It often looks white to our eyes because its light is weak.","A nearly full, low moon and water drops can make one possible."],"revealExplanation":"A long-exposure photo can show its faint colors.","sources":[{"title":"Met Office: Rainbows","url":"https://weather.metoffice.gov.uk/learn-about/weather/optical-effects/rainbows"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["light","weather"]},{"id":"bk-nature-013","canonicalKnowledgeId":"bk-nature-013","locale":"en","term":"Alexander's band","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Light and vision"],"secretAnswer":"Alexander's band is the darker area between the two bows of a double rainbow.","supportingFacts":["The outer rainbow is fainter than the inner one.","The outer bow's colors run in the opposite order."],"revealExplanation":"Less rainbow light reaches your eyes from the area between the bows.","sources":[{"title":"Met Office: Rainbows","url":"https://weather.metoffice.gov.uk/learn-about/weather/optical-effects/rainbows"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["light","weather"]},{"id":"bk-nature-014","canonicalKnowledgeId":"bk-nature-014","locale":"en","term":"Tafoni","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Rock formations","Cooking","Musical instruments"],"secretAnswer":"Tafoni are small, rounded holes in a rock surface that can look like a honeycomb.","supportingFacts":["Groups of holes can make the rock look like a sponge.","They often occur in dry or partly dry areas."],"revealExplanation":"At Arches, water helps weaken the material holding sandstone together.","sources":[{"title":"National Park Service: Tafoni","url":"https://home.nps.gov/articles/tafoni.htm"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["geology","weathering"]},{"id":"bk-nature-015","canonicalKnowledgeId":"bk-nature-015","locale":"en","term":"Fulgurite","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A fulgurite is glass formed when lightning melts sand in the ground.","supportingFacts":["In sand dunes, it can form dark glass tubes.","The name comes from the Latin word for lightning."],"revealExplanation":"The tubes preserve part of the path of a lightning strike through sand.","sources":[{"title":"National Park Service: Fulgurites","url":"https://home.nps.gov/articles/grsa-fulgurites.htm"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["geology","lightning"]},{"id":"bk-nature-016","canonicalKnowledgeId":"bk-nature-016","locale":"en","term":"Fallstreak hole","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Weather"],"secretAnswer":"A fallstreak hole is a large round or oval gap that forms when ice grows and falls out of a cloud.","supportingFacts":["The cloud can contain liquid drops colder than freezing.","An aircraft passing through can help start the freezing."],"revealExplanation":"The gap can grow as nearby drops freeze and fall.","sources":[{"title":"NOAA National Weather Service: Fallstreaks","url":"https://www.weather.gov/arx/why_fallstreaks"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["weather","clouds"]},{"id":"bk-nature-017","canonicalKnowledgeId":"bk-nature-017","locale":"en","term":"Desert varnish","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Rock formations","Painting","Cooking"],"secretAnswer":"Desert varnish is a thin natural coating that gives exposed rocks dark or reddish colors.","supportingFacts":["It may contain clay and iron or manganese oxides.","Its material is different from the rock beneath it."],"revealExplanation":"People have made rock carvings by cutting through the dark surface to reveal lighter rock.","sources":[{"title":"National Park Service: Desert Varnish","url":"https://www.nps.gov/articles/desertvarnish.htm"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["geology","rock-surfaces"]},{"id":"bk-nature-018","canonicalKnowledgeId":"bk-nature-018","locale":"en","term":"Pillow lava","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"Pillow lava is rounded lumps of rock formed when lava cools quickly in water.","supportingFacts":["The outside cools into a glassy skin.","Hot lava inside can keep making the lump larger."],"revealExplanation":"The lumps can pile up in thick stacks.","sources":[{"title":"US Geological Survey: Pillow lava","url":"https://www.usgs.gov/observatories/calvo/news/dont-try-have-a-pillow-fight-these-pillows"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["geology","volcanoes"]},{"id":"bk-nature-019","canonicalKnowledgeId":"bk-nature-019","locale":"en","term":"Yardang","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Rock formations"],"secretAnswer":"A yardang is a ridge of rock shaped by wind wearing away the surrounding material.","supportingFacts":["Wind can carry away loose sand grains from the rock.","NASA has photographed yardangs on Mars."],"revealExplanation":"Their shape records the action of rock-wearing winds.","sources":[{"title":"NASA: Wind Erosion in Tithonium","url":"https://science.nasa.gov/photojournal/wind-erosion-in-tithonium/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["geology","wind"]},{"id":"bk-nature-020","canonicalKnowledgeId":"bk-nature-020","locale":"en","term":"Helictite","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Rock formations","Sea life","Clothing"],"secretAnswer":"A helictite is a twisted mineral growth in a cave that can grow in many directions.","supportingFacts":["It can grow on cave ceilings or walls.","Water moves through tiny channels inside it."],"revealExplanation":"Some look like thin branches or antlers rather than straight hanging points.","sources":[{"title":"National Park Service: Speleothems","url":"https://home.nps.gov/subjects/caves/speleothems.htm"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["geology","caves"]},{"id":"bk-nature-021","canonicalKnowledgeId":"bk-nature-021","locale":"en","term":"Pele's hair","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"Pele's hair is thin strands of volcanic glass made when liquid lava is stretched and cools in air.","supportingFacts":["It forms from very fluid lava.","Wind can carry the light strands away from a volcano."],"revealExplanation":"The strands are fragile and can break into sharp glass pieces.","sources":[{"title":"US Geological Survey: Pele's hairs","url":"https://www.usgs.gov/observatories/hvo/news/volcano-watch-peles-hairs-a-beautiful-hazard-island-hawaii"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["geology","volcanoes"]},{"id":"bk-nature-022","canonicalKnowledgeId":"bk-nature-022","locale":"en","term":"Pele's tears","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Rock formations"],"secretAnswer":"Pele's tears are small droplets of volcanic glass made from liquid lava.","supportingFacts":["They can occur in a cloud of cooled lava pieces above a lava fountain.","They are droplets, while Pele's hair forms thin strands."],"revealExplanation":"Very fluid lava can form drops rather than long strings.","sources":[{"title":"US Geological Survey: Hawaiian lava fountain and volcanic glass","url":"https://www.usgs.gov/media/images/lava-fountain-reaches-high-445-m-1460-ft-during-episode-30"},{"title":"US Geological Survey: Pele's hairs","url":"https://www.usgs.gov/observatories/hvo/news/volcano-watch-peles-hairs-a-beautiful-hazard-island-hawaii"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["geology","volcanoes"]},{"id":"bk-nature-023","canonicalKnowledgeId":"bk-nature-023","locale":"en","term":"Kleptoplasty","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Living things","Crime","Metalworking"],"secretAnswer":"Kleptoplasty is when an organism takes the light-catching parts of its food and keeps using them in its own cells.","supportingFacts":["Some sea slugs take these parts from algae they eat.","The stolen parts can still use sunlight to provide energy."],"revealExplanation":"The name's first part comes from a Greek word for thief.","sources":[{"title":"University of Hawaii: Kleptoplasty","url":"https://manoa.hawaii.edu/exploringourfluidearth/biological/aquatic-plants-and-algae/structure-and-function/weird-science-kleptoplasty"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["biology","sea-slugs"]},{"id":"bk-nature-024","canonicalKnowledgeId":"bk-nature-024","locale":"en","term":"Witch's broom","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"A witch's broom is a dense bunch of unusually short shoots growing together on a tree or other woody plant.","supportingFacts":["Diseases, mites, or mutations can cause it.","Many short shoots can grow after a main growing point dies."],"revealExplanation":"Some caused by mutations are used to grow dwarf plants.","sources":[{"title":"University of Maryland Extension: Witches' Broom on Trees","url":"https://www.extension.umd.edu/resource/witches-broom-trees"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["plants","growth"]},{"id":"bk-nature-025","canonicalKnowledgeId":"bk-nature-025","locale":"en","term":"Guttation","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Plant behavior"],"secretAnswer":"Guttation is when pressure in a plant's roots pushes liquid water out at the edges of its leaves.","supportingFacts":["It can be seen on lawn grass.","The drops often appear in the morning after little water has evaporated."],"revealExplanation":"The water comes from inside the plant.","sources":[{"title":"Nature Education: Water Uptake and Transport in Vascular Plants","url":"https://www.nature.com/scitable/knowledge/library/water-uptake-and-transport-in-vascular-plants-103016037/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["plants","water"]},{"id":"bk-nature-026","canonicalKnowledgeId":"bk-nature-026","locale":"en","term":"Countershading","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Animal adaptations","Painting","Architecture"],"secretAnswer":"Countershading is coloring with a dark upper side and a light lower side that helps an animal blend in.","supportingFacts":["From above, the dark side can match deep water.","From below, the light side can match the bright surface."],"revealExplanation":"Tuna, sharks, dolphins, and sea turtles use this form of camouflage.","sources":[{"title":"Monterey Bay Aquarium: Open ocean","url":"https://www.montereybayaquarium.org/animals-the-ocean/ecosystems/open-ocean"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["animals","camouflage"]},{"id":"bk-nature-027","canonicalKnowledgeId":"bk-nature-027","locale":"en","term":"Marcescence","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"Marcescence is when a plant keeps dead leaves attached instead of dropping them at the usual time.","supportingFacts":["Oaks and beech trees can keep dead leaves through winter.","New spring growth can push the old leaves off."],"revealExplanation":"Researchers have several ideas about its benefits, but the reason is not settled.","sources":[{"title":"University of Georgia Extension: Trees that hold their leaves","url":"https://site.extension.uga.edu/forsyth/trees-that-hold-their-leaves/"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["plants","leaves"]},{"id":"bk-nature-028","canonicalKnowledgeId":"bk-nature-028","locale":"en","term":"Plant vivipary","publicPrompt":"What does this mean?","hintMode":"category","publicHints":["Plant behavior"],"secretAnswer":"Plant vivipary is when a seed starts growing while still inside or attached to its parent plant.","supportingFacts":["It can happen inside a tomato.","For some mangroves, it is a normal way to develop."],"revealExplanation":"A mangrove seedling can drop with a long root that sticks into soft wet soil.","sources":[{"title":"University of Florida: Vivipary","url":"https://propg.ifas.ufl.edu/04-seeds/01-development/11-seedsdevelopment-vivipary.html"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["plants","seeds"]},{"id":"bk-nature-029","canonicalKnowledgeId":"bk-nature-029","locale":"en","term":"Nyctinasty","publicPrompt":"What does this mean?","hintMode":"choices","publicHints":["Plant behavior","Dance","Body language"],"secretAnswer":"Nyctinasty is the daily movement of some plant leaves as day turns to night.","supportingFacts":["Shamrock plants fold their leaves at night and open them in morning light.","Special cells at the leaf base swell or shrink to move it."],"revealExplanation":"The leaves can look as if they are going to sleep.","sources":[{"title":"University of Missouri Extension: Shamrock plants","url":"https://extension.missouri.edu/news/shamrock-plants-rockin-by-day-dozin-at-night"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["plants","movement"]},{"id":"bk-nature-030","canonicalKnowledgeId":"bk-nature-030","locale":"en","term":"Masting","publicPrompt":"What does this mean?","hintMode":"none","publicHints":[],"secretAnswer":"Masting is when trees or shrubs produce a huge seed crop in some years and much less in others.","supportingFacts":["Their fruits and seeds are an important food for wildlife.","Oaks and beech trees have years with heavy nut crops."],"revealExplanation":"Weather, species, and genetics all help affect how much seed is produced.","sources":[{"title":"University of New Hampshire Extension: Mast","url":"https://extension.unh.edu/goodforestry/html/6-1.htm"}],"verificationStatus":"verified","verifiedAt":"2026-10-06","enabled":true,"tags":["plants","seeds"]}];if(typeof module==='object'&&module.exports)module.exports=cards;else root.BLUFF_QUESTIONS=cards;})(typeof globalThis!=='undefined'?globalThis:this);
